using System.Globalization;
using System.Text.Json;
using Nro.Data.Db;
using Nro.Data.Repositories.Top;
using Nro.Tests.Integration.Db.Players;

namespace Nro.Tests.Integration.Db.Top;

/// <summary>
/// <see cref="TopRepository"/> against the rankings produced by the REAL <c>TopDAO.java</c> SQL on MariaDB 10.4 (<c>tests/golden/top-ranking.json</c>, regenerated by
/// <c>port-csharp/tools/top/gen_top_golden.py</c> on synthetic data). Five datasets: <c>ties</c> (many equal values), <c>distinct</c> (no tie: the order must match rank by rank),
/// <c>edge</c> (NULL, <c>null</c>, malformed and hostile JSON), <c>wrap</c> and <c>overflow</c> (unsigned wrap-around of gold bars).
/// </summary>
/// <remarks>
/// MariaDB's order among equal values is undefined, so equal-value groups are compared as sets (see <see cref="AssertSameRanking"/>); the group that the LIMIT cuts through may
/// contain any members of its tie set. The tie-break of the C# code (player id ascending) is pinned separately in <see cref="TopRepositoryTests"/>.
/// </remarks>
[Collection(PlayerAccountDatabaseCollection.Name)]
public class TopRepositoryGoldenTests : IClassFixture<TopFixture>, IAsyncLifetime
{
    private static readonly string[] NotPorted = ["TOP_SK", "TOP_NHS", "TOP_DC", "TOP_3_WHIS"];

    private readonly TopFixture _fixture;

    public TopRepositoryGoldenTests(TopFixture fixture)
    {
        _fixture = fixture;
    }

    private ITopRepository Repository => new TopRepository(_fixture.Db);

    public static IEnumerable<object[]> Rankings()
    {
        var golden = Golden.Value;
        foreach (var (dataset, rankings) in golden.Rankings)
        {
            foreach (var constant in rankings.Keys.Where(k => !NotPorted.Contains(k)).OrderBy(k => k, StringComparer.Ordinal))
            {
                if (dataset == "overflow" && constant == "TOP_THOI_VANG")
                {
                    continue; // MariaDB fails the whole query there; covered by Gold_bar_sum_overflow_fails_in_mariadb_and_saturates_here
                }

                yield return [dataset, constant];
            }
        }
    }

    public Task InitializeAsync() => Task.CompletedTask;

    public Task DisposeAsync() => Task.CompletedTask;

    [Theory]
    [MemberData(nameof(Rankings))]
    public async Task Ranking_equals_what_the_java_sql_returned_on_mariadb(string dataset, string constant)
    {
        var golden = Golden.Value;
        await _fixture.EnsureDatasetAsync(dataset, golden.Players[dataset]);
        var expected = golden.Rankings[dataset][constant];
        Assert.Null(expected.Error);

        var actual = await Cases[constant](Repository);

        AssertSameRanking(dataset, constant, expected, actual);
        if (dataset == "distinct" && constant != "TOP_THOI_VANG")
        {
            // No tie anywhere in this dataset, so the order must be identical rank by rank.
            Assert.Equal(expected.Rows.Select(r => r.Id), actual.Select(r => r.Id));
        }
    }

    [Fact]
    public void Every_constant_of_TopDAO_is_ported_or_proved_unusable()
    {
        var golden = Golden.Value;
        Assert.Equal(50, golden.Sql.Count);
        foreach (var constant in golden.Sql.Keys)
        {
            if (NotPorted.Contains(constant))
            {
                // These four fail on the real database too (ambiguous column / unknown column / unknown function), in every dataset.
                Assert.All(golden.Rankings.Values, rankings => Assert.NotNull(rankings[constant].Error));
            }
            else
            {
                Assert.True(Cases.ContainsKey(constant), constant + " has no C# counterpart");
            }
        }

        Assert.Equal(46, Cases.Count);
    }

    [Fact]
    public void Gold_bar_sum_overflow_fails_in_mariadb_and_saturates_here()
    {
        var golden = Golden.Value;
        Assert.Contains("1690", golden.Rankings["overflow"]["TOP_THOI_VANG"].Error);
        Assert.Null(golden.Rankings["wrap"]["TOP_THOI_VANG"].Error);
    }

    [Fact]
    public async Task Gold_bar_sum_overflow_does_not_break_the_ranking()
    {
        await _fixture.EnsureDatasetAsync("overflow", Golden.Value.Players["overflow"]);

        var top = await Repository.GetTopThoiVangAsync();

        // player 4: bag saturates at 2^64-1 and the chest adds 5 (MariaDB: error 1690); player 2: 2^64-1; player 1: 2^64-3 (wrap of -3); player 3: 40+2
        Assert.Equal(new[] { 4, 2, 1, 3 }, top.Select(e => e.PlayerId));
        Assert.Equal(ulong.MaxValue, top[0].Total);
        Assert.Equal(5UL, top[0].BoxQuantity);
        Assert.Equal(ulong.MaxValue, top[1].Total);
        Assert.Equal(18446744073709551613UL, top[2].Total);
        Assert.Equal(42UL, top[3].Total);
    }

    [Fact]
    public async Task Wrap_dataset_matches_mariadb_exactly()
    {
        var golden = Golden.Value;
        await _fixture.EnsureDatasetAsync("wrap", golden.Players["wrap"]);

        var actual = await Cases["TOP_THOI_VANG"](Repository);

        Assert.Equal(golden.Rankings["wrap"]["TOP_THOI_VANG"].Rows.Select(r => r.Id), actual.Select(r => r.Id));
        AssertSameRanking("wrap", "TOP_THOI_VANG", golden.Rankings["wrap"]["TOP_THOI_VANG"], actual);
    }

    /// <summary>
    /// Groups the golden rows by their ORDER BY key. For every group: the C# rows at the same positions must belong to the tie set of that key (the golden rows plus, for the
    /// group cut by the LIMIT, the rows MariaDB left out), the group sizes must be equal (a group that is not the last must be the same set of players), and every value must be the
    /// one MariaDB returned for that player (for a player MariaDB left out, only the columns of the key can be compared).
    /// </summary>
    private static void AssertSameRanking(string dataset, string constant, GoldenRanking expected, IReadOnlyList<RankRow> actual)
    {
        var label = dataset + "/" + constant;
        Assert.True(expected.Rows.Count == actual.Count, $"{label}: expected {expected.Rows.Count} rows, got {actual.Count}");
        Assert.Equal(expected.Rows.Count, actual.Select(r => r.Id).Distinct().Count());

        var position = 0;
        while (position < expected.Rows.Count)
        {
            var key = expected.Rows[position].KeyText;
            var end = position;
            while (end < expected.Rows.Count && expected.Rows[end].KeyText == key)
            {
                end++;
            }

            var groupIds = expected.Rows.Skip(position).Take(end - position).Select(r => r.Id).ToHashSet();
            var tieSet = expected.TieSets.TryGetValue(key, out var ties) ? ties.ToHashSet() : groupIds;
            for (var i = position; i < end; i++)
            {
                var row = actual[i];
                Assert.True(tieSet.Contains(row.Id), $"{label}: rank {i + 1} is player {row.Id}, which is not in the tie set of key {key}");
                if (expected.ById.TryGetValue(row.Id, out var golden))
                {
                    Assert.True(
                        golden.Values.SequenceEqual(row.Values),
                        $"{label}: rank {i + 1} (player {row.Id}) values [{string.Join(", ", row.Values)}] differ from MariaDB [{string.Join(", ", golden.Values)}]");
                }
                else
                {
                    var head = expected.Rows[position];
                    Assert.True(
                        expected.KeyIndexes.All(k => head.Values[k] == row.Values[k]),
                        $"{label}: rank {i + 1} (player {row.Id}) has other key values than MariaDB's group");
                }
            }

            if (end < expected.Rows.Count)
            {
                Assert.True(
                    actual.Skip(position).Take(end - position).Select(r => r.Id).ToHashSet().SetEquals(groupIds),
                    $"{label}: the tie group at ranks {position + 1}-{end} is not the same set of players as in MariaDB");
            }

            position = end;
        }
    }

    private static string Unsigned(long value) => unchecked((ulong)value).ToString(CultureInfo.InvariantCulture);

    private static string Signed(long value) => value.ToString(CultureInfo.InvariantCulture);

    private static async Task<IReadOnlyList<RankRow>> Scalar(ITopRepository repository, TopRanking ranking, bool unsigned)
    {
        var rows = await repository.GetTopAsync(ranking);
        return rows.Select(r => new RankRow(r.PlayerId, [unsigned ? Unsigned(r.Value) : Signed(r.Value)])).ToList();
    }

    private static readonly Dictionary<string, Func<ITopRepository, Task<IReadOnlyList<RankRow>>>> Cases = BuildCases();

    private static Dictionary<string, Func<ITopRepository, Task<IReadOnlyList<RankRow>>>> BuildCases()
    {
        var cases = new Dictionary<string, Func<ITopRepository, Task<IReadOnlyList<RankRow>>>>();
        void Add(string constant, TopRanking ranking, bool unsigned = true) => cases[constant] = repository => Scalar(repository, ranking, unsigned);

        Add("TOP_MAY_DAM_TRAI_DAT", TopRanking.PunchingMachineEarthling);
        Add("TOP_MAY_DAM_NAMEC", TopRanking.PunchingMachineNamekian);
        Add("TOP_MAY_DAM_XAYDA", TopRanking.PunchingMachineSaiyan);
        Add("TOP_SM", TopRanking.Power);
        Add("TOP_HP", TopRanking.Hp);
        Add("TOP_KI", TopRanking.Ki);
        Add("TOP_SD", TopRanking.Damage);
        Add("TOP_SM_PET", TopRanking.PetPower);
        Add("TOP_HP_PET", TopRanking.PetHp);
        Add("TOP_KI_PET", TopRanking.PetKi);
        Add("TOP_SD_PET", TopRanking.PetDamage);
        Add("TOP_VND", TopRanking.Vnd, unsigned: false);
        Add("TOP_COIN", TopRanking.Coin, unsigned: false);
        Add("TOP_HONG_NGOC", TopRanking.Ruby);
        Add("TOP_DA_NAP", TopRanking.TotalTopUp, unsigned: false);
        Add("TOP_NAMEK_WAR", TopRanking.NamekWar, unsigned: false);
        Add("TOP_MO_LIXI", TopRanking.OpenLuckyMoney);
        Add("TOP_TANG_LIXI", TopRanking.GiveLuckyMoney);
        Add("TOP_BAN_PHAO_HOA", TopRanking.LaunchFireworks);
        Add("TOP_BAN_PHAO_HOA_VIP", TopRanking.LaunchFireworksVip);
        Add("TOP_TRANG_TRI_CAY_NOEL", TopRanking.DecorateChristmasTree);
        Add("CHE_TAO_NGUOI_TUYET", TopRanking.CraftSnowman);
        Add("CHE_TAO_NGUOI_TUYET_BANG_GIA", TopRanking.CraftFrozenSnowman);
        Add("TOP_DOT_DIEM", TopRanking.BurnMatches);
        Add("TOP_DOT_PHAO_VU_LAN", TopRanking.BurnVuLanFirecrackers);
        Add("TOP_HOA_DANG", TopRanking.FlowerLantern);
        Add("TOP_HOA_DANG_LOI_CHUC", TopRanking.FlowerLanternWish);
        Add("TOP_MO_HOP_QUA_MA_QUY", TopRanking.OpenGhostGiftBox);
        Add("TOP_THIEP_HALLOWEEN", TopRanking.HalloweenCard);
        Add("TOP_MO_THIEP_83", TopRanking.OpenWomensDayCard);
        Add("TOP_TANG_BONG_HOA_HONG", TopRanking.GiveRoses);
        Add("TOP_LAM_BANH_TRUNG_THU", TopRanking.MakeMoonCake);
        Add("TOP_MO_BANH_TRUNG_THU_DAC_BIET", TopRanking.OpenSpecialMoonCake);
        Add("TOP_MO_TRUNG_VANG", TopRanking.OpenGoldenEgg);
        Add("TOP_MO_HOP_QUA_GIO_TO", TopRanking.OpenHungKingGiftBox);
        Add("TOP_DANG_BANH", TopRanking.OfferCakes);
        Add("TOP_DOI_DUA_HAU", TopRanking.ExchangeWatermelon);
        Add("TOP_MO_HOP_BLACK_FRIDAY", TopRanking.OpenBlackFridayBox);
        Add("TOP_MUA_SAM_BLACK_FRIDAY", TopRanking.BlackFridayShopping);
        Add("TOP_PVP", TopRanking.Pvp);
        Add("TOP_NAP", TopRanking.TopUp);
        Add("TOP_DUA_NAP", TopRanking.TopUpRace);

        cases["TOP_NV"] = async repository =>
            (await repository.GetTopNvAsync())
            .Select(r => new RankRow(r.PlayerId, [Unsigned(r.Task), Unsigned(r.SubTask), Unsigned(r.Progress), TopFixture.FormatTimestamp(r.LastTimeLoginGame)]))
            .ToList();
        cases["TOP_WHIS"] = async repository =>
            (await repository.GetTopWhisAsync())
            .Select(r => new RankRow(r.PlayerId, [Unsigned(r.Top), Unsigned(r.Time), TopFixture.FormatTimestamp(r.LastTimeLoginGame)]))
            .ToList();
        cases["TOP_VDST"] = async repository =>
            (await repository.GetTopVdstAsync())
            .Select(r => new RankRow(r.PlayerId, [Unsigned(r.Field2), Unsigned(r.Time)]))
            .ToList();
        cases["TOP_THOI_VANG"] = async repository =>
            (await repository.GetTopThoiVangAsync())
            .Select(r => new RankRow(r.PlayerId, [r.BagQuantity.ToString(CultureInfo.InvariantCulture), r.BoxQuantity.ToString(CultureInfo.InvariantCulture), r.Total.ToString(CultureInfo.InvariantCulture)]))
            .ToList();
        return cases;
    }

    private sealed record RankRow(int Id, string[] Values);

    private sealed record GoldenRow(int Id, string KeyText, string[] Values);

    private sealed record GoldenRanking(string? Error, IReadOnlyList<GoldenRow> Rows, IReadOnlyDictionary<string, int[]> TieSets, int[] KeyIndexes)
    {
        public IReadOnlyDictionary<int, GoldenRow> ById { get; } = Rows.ToDictionary(r => r.Id);
    }

    private sealed class Golden
    {
        private static readonly Lazy<Golden> Cached = new(Load);

        public static Golden Value => Cached.Value;

        public required IReadOnlyDictionary<string, string> Sql { get; init; }

        public required IReadOnlyDictionary<string, IReadOnlyList<TopPlayer>> Players { get; init; }

        public required IReadOnlyDictionary<string, IReadOnlyDictionary<string, GoldenRanking>> Rankings { get; init; }

        private static Golden Load()
        {
            using var stream = File.OpenRead(TestPaths.Golden("top-ranking.json"));
            using var document = JsonDocument.Parse(stream);
            var root = document.RootElement;

            var sql = root.GetProperty("sql").EnumerateObject().ToDictionary(p => p.Name, p => p.Value.GetString()!);
            var players = root.GetProperty("datasets").EnumerateObject()
                .ToDictionary(d => d.Name, d => (IReadOnlyList<TopPlayer>)d.Value.EnumerateArray().Select(TopPlayer.FromJson).ToList());
            var rankings = new Dictionary<string, IReadOnlyDictionary<string, GoldenRanking>>();
            foreach (var dataset in root.GetProperty("golden").EnumerateObject())
            {
                var byConstant = new Dictionary<string, GoldenRanking>();
                foreach (var ranking in dataset.Value.EnumerateObject())
                {
                    byConstant[ranking.Name] = ParseRanking(ranking.Value);
                }

                rankings[dataset.Name] = byConstant;
            }

            return new Golden { Sql = sql, Players = players, Rankings = rankings };
        }

        private static GoldenRanking ParseRanking(JsonElement element)
        {
            if (element.GetProperty("error").ValueKind != JsonValueKind.Null)
            {
                return new GoldenRanking(element.GetProperty("error").GetString(), [], new Dictionary<string, int[]>(), []);
            }

            var valueColumns = element.GetProperty("valueColumns").EnumerateArray().Select(c => c.GetString()!).ToArray();
            var keyIndexes = element.GetProperty("orderColumns").EnumerateArray().Select(c => Array.IndexOf(valueColumns, c.GetString()!)).ToArray();
            Assert.DoesNotContain(-1, keyIndexes);
            var rows = element.GetProperty("rows").EnumerateArray()
                .Select(r => new GoldenRow(
                    r.GetProperty("id").GetInt32(),
                    KeyText(r.GetProperty("key")),
                    valueColumns.Select(c => Normalise(r.GetProperty("v").GetProperty(c))).ToArray()))
                .ToList();
            var ties = element.GetProperty("tieSets").EnumerateObject()
                .ToDictionary(p => KeyText(JsonDocument.Parse(p.Name).RootElement), p => p.Value.EnumerateArray().Select(i => i.GetInt32()).ToArray());
            return new GoldenRanking(null, rows, ties, keyIndexes);
        }

        // One text per key vector, independent of how the JSON was indented (SQL NULL stays distinct from the string "0").
        private static string KeyText(JsonElement key)
            => string.Join("|", key.EnumerateArray().Select(e => e.ValueKind == JsonValueKind.Null ? "NULL" : e.GetString()!));

        // Java read these with getInt/getLong: SQL NULL is 0. Timestamps are already text.
        private static string Normalise(JsonElement value) => value.ValueKind == JsonValueKind.Null ? "0" : value.GetString()!;
    }
}
